18	// DEVDESK-717 (step 3 of DEVDESK-708): the confirmation of the Ports tab acts on
19	// the target it captured when it opened (S-01a criteria 5 and 6, bug
20	// DEVDESK-714), and says the truth on Windows (S-02a criteria 1 to 4).
21	//
22	// No test here reaches ports.Kill: every model installs a fake processOps whose
23	// kill only records the PID it was asked to signal.
24	
25	// fakeProcs records the PIDs the Ports tab asked to signal.
26	type fakeProcs struct {
27		killed []string
28		err    error
29		// protect is the verdict per PID; a PID not in it is Unprotected. asked
30		// records every PID the model asked about, in order (DEVDESK-718).
31		protect map[string]ports.Protection
32		asked   []string
33	}
34	
35	func (f *fakeProcs) ops(windows bool) processOps {
36		return processOps{
37			protection: func(pid string) ports.Protection {
38				f.asked = append(f.asked, pid)
39				return f.protect[pid]
40			},
41			kill: func(pid string, _ ports.Identity) error {
42				f.killed = append(f.killed, pid)
43				return f.err
44			},
45			windows: windows,
46		}
47	}
48	
49	// protectAs makes the fake say p about pid from now on.
50	func (f *fakeProcs) protectAs(pid string, p ports.Protection) {
51		if f.protect == nil {
52			f.protect = map[string]ports.Protection{}
53		}
54		f.protect[pid] = p
55	}
56	
57	// installProcs puts a fresh recording fake on the model and returns it.
58	func installProcs(m *Model, windows bool) *fakeProcs {
59		f := &fakeProcs{}
60		m.portsModel.ops = f.ops(windows)
61		return f
62	}
63	
64	// sock is a LISTEN socket held by pid; the port follows the PID so rows differ.
65	func sock(pid, process string) ports.Socket {
66		return ports.Socket{
67			Protocol: "tcp", State: "LISTEN", LocalAddr: "0.0.0.0:" + pid, PeerAddr: "0.0.0.0:*",
68			PID: pid, Process: process,
69		}
70	}
71	
72	// nodeFirst and nodeLast are the same sockets in two orders: the refresh of the
73	// table reorders them while a confirmation is open (DEVDESK-714).
74	func nodeFirst() []ports.Socket {
75		return []ports.Socket{sock("4242", "node"), sock("812", "sshd"), sock("1204", "nginx")}
76	}
77	
78	func nodeLast() []ports.Socket {
79		return []ports.Socket{sock("812", "sshd"), sock("1204", "nginx"), sock("4242", "node")}
80	}
81	
82	// confirmOnNode returns a wide model whose cursor is on node (PID 4242) with
83	// the confirmation open, and the fake that records signals.
84	func confirmOnNode(t *testing.T) (*Model, *fakeProcs) {
85		t.Helper()
86		m := feed(t, portsModel(t), tea.WindowSizeMsg{Width: 160, Height: 40})
87		m = feed(t, m, portsDataMsg{ports: nodeFirst()})
88		m.portsModel.table.Table().SetCursor(0)
89		procs := installProcs(m, false)
90		if row, ok := m.portsModel.table.Selected(); !ok || row.PID != "4242" {
91			t.Fatalf("setup: selected row = %+v, want node (PID 4242)", row)
92		}
93		m = feed(t, m, testutil.Key(keymap.Kill))
94		if m.portsModel.confirmModal == nil {
95			t.Fatal("setup: K on node did not open the confirmation")
96		}
97		return m, procs
98	}
99	
100	// runKill executes the command a confirmed Yes returned. It must be the kill
101	// command itself, with no footer timer batched in (that would sleep 3 s).
102	func runKill(t *testing.T, cmd tea.Cmd) portsKillResultMsg {
103		t.Helper()
104		if cmd == nil {
105			t.Fatal("Yes returned no command")
106		}
107		res, ok := cmd().(portsKillResultMsg)
108		if !ok {
109			t.Fatalf("the command did not return a portsKillResultMsg")
110		}
111		return res
112	}
113	
114	// modalLines is the confirmation as rendered, border and padding removed, one
115	// entry per content line, stopping before the buttons.
116	func modalLines(m *Model) []string {
117		var out []string
118		for _, l := range strings.Split(ansi.Strip(m.portsModel.confirmModal.View()), "\n") {
119			l = strings.TrimSpace(strings.Trim(strings.TrimSpace(l), "│┌┐└┘─"))
120			if strings.Contains(l, "Yes") && strings.Contains(l, "No") {
121				break
122			}
123			out = append(out, l)
124		}
125		for len(out) > 0 && out[0] == "" {
126			out = out[1:]
127		}
128		for len(out) > 0 && out[len(out)-1] == "" {
129			out = out[:len(out)-1]
130		}
131		return out
132	}
133	
134	// modalTitle and modalBody split modalLines at the title's blank line.
135	func modalTitle(m *Model) string { return modalLines(m)[0] }
136	
137	func modalBody(m *Model) string {
138		return strings.TrimLeft(strings.Join(modalLines(m)[1:], "\n"), "\n")
139	}
140	
141	// squash folds every run of whitespace into one space.
142	func squash(s string) string { return strings.Join(strings.Fields(s), " ") }
