144	// ── S-01a criterion 5 and the DEVDESK-714 bug ────────────────────────────────
145	
146	func TestYesKillsTheCapturedTargetAfterTheTableReorders(t *testing.T) {
147		m, procs := confirmOnNode(t)
148	
149		// The refresh lands before the user answers. The cursor stays on index 0,
150		// which is now sshd: the pre-fix code killed that row.
151		m = feed(t, m, portsDataMsg{ports: nodeLast()})
152		if row, _ := m.portsModel.table.Selected(); row.PID != "812" {
153			t.Fatalf("setup: after the reorder the selected row is %+v, want sshd (PID 812)", row)
154		}
155	
156		m, cmd := step(t, m, components.ConfirmModalYesMsg{})
157		res := runKill(t, cmd)
158	
159		if res.pid != "4242" {
160			t.Errorf("kill result pid = %q, want 4242", res.pid)
161		}
162		if len(procs.killed) != 1 || procs.killed[0] != "4242" {
163			t.Errorf("signalled PIDs = %v, want exactly [4242] (never the selected row, 812)", procs.killed)
164		}
165		if !m.portsModel.table.IsBusy("4242") {
166			t.Error("the captured target is not marked busy")
167		}
168		if m.portsModel.table.IsBusy("812") {
169			t.Error("the row under the cursor was marked busy: Yes read the selection")
170		}
171		if m.portsModel.confirmModal != nil || m.portsModel.pendingKill != nil {
172			t.Error("the confirmation or its captured target survived Yes")
173		}
174	}
