176	// Rule 110: the command receives values, never the model. Whatever happens to
177	// the model between Yes and the moment the command runs, the signal goes to the
178	// PID captured in Update and through the function captured in Update.
179	func TestTheKillCommandCarriesValuesNotTheModel(t *testing.T) {
180		m, procs := confirmOnNode(t)
181		m, cmd := step(t, m, components.ConfirmModalYesMsg{})
182	
183		m.portsModel.table.SetItems(nodeLast())
184		m.portsModel.table.Table().SetCursor(2)
185		m.portsModel.pendingKill = nil
186		m.portsModel.ops = processOps{kill: func(string, ports.Identity) error {
187			panic("the command read the model's processOps after Update returned")
188		}}
189	
190		res := runKill(t, cmd)
191	
192		if res.pid != "4242" || len(procs.killed) != 1 || procs.killed[0] != "4242" {
193			t.Errorf("result pid = %q, signalled = %v, want 4242 through the function captured in Update", res.pid, procs.killed)
194		}
195	}
