197	func TestTheConfirmationShowsTheCapturedNameAndPID(t *testing.T) {
198		m, _ := confirmOnNode(t)
199	
200		want := killTarget{PID: "4242", Process: "node"}
201		if m.portsModel.pendingKill == nil || *m.portsModel.pendingKill != want {
202			t.Fatalf("pendingKill = %+v, want %+v", m.portsModel.pendingKill, want)
