209	// A confirmation is only ever answered by a message from the modal: a Yes that
210	// arrives with nothing open used to kill whatever the cursor stood on.
211	func TestAStrayYesKillsNothing(t *testing.T) {
212		m := portsModel(t)
213		procs := installProcs(m, false)
214		m.portsModel.table.Table().SetCursor(0) // sshd, PID 812
