231	func TestTheConfirmationDoesNotFollowTheSelection(t *testing.T) {
232		for _, tt := range []struct {
233			name string
234			then []tea.Msg
235		}{
236			{"the selection moves", append(testutil.Keys("down", "down", "up"), portsDataMsg{ports: nodeLast()})},
237			{"the process disappears", []tea.Msg{portsDataMsg{ports: []ports.Socket{sock("812", "sshd"), sock("1204", "nginx")}}}},
238			{"the table empties", []tea.Msg{portsDataMsg{ports: nil}}},
239		} {
240			t.Run(tt.name, func(t *testing.T) {
241				m, procs := confirmOnNode(t)
242				before := ansi.Strip(m.portsModel.confirmModal.View())
243	
244				m = feed(t, m, tt.then...)
