252				if want := (killTarget{PID: "4242", Process: "node"}); m.portsModel.pendingKill == nil || *m.portsModel.pendingKill != want {
253					t.Errorf("pendingKill = %+v, want %+v", m.portsModel.pendingKill, want)
254				}
255				if len(procs.killed) != 0 {
256					t.Errorf("signalled %v without an answer", procs.killed)
257				}
258			})
