304	const goneWarning = "node (PID 4242) is no longer listed — not stopped"
305	
306	func TestYesOnAVanishedTargetSendsNothing(t *testing.T) {
307		for _, tt := range []struct {
308			name  string
309			table []ports.Socket
310		}{
311			{"the PID is gone", []ports.Socket{sock("812", "sshd"), sock("1204", "nginx")}},
312			{"the PID is back under another name", []ports.Socket{sock("4242", "python"), sock("812", "sshd")}},
313			{"the table is empty", nil},
314		} {
315			t.Run(tt.name, func(t *testing.T) {
316				m, procs := confirmOnNode(t)
317				m = feed(t, m, portsDataMsg{ports: tt.table})
318	
319				m, cmd := step(t, m, components.ConfirmModalYesMsg{})
320	
321				if len(procs.killed) != 0 {
322					t.Errorf("signalled %v for a target that is no longer listed", procs.killed)
323				}
324				if cmd == nil {
325					t.Error("no command returned, so the footer warning would never clear")
326				}
327				if got := m.portsModel.footer.Text(); got != goneWarning {
328					t.Errorf("footer = %q, want %q", got, goneWarning)
329				}
330				if got := m.portsModel.footer.Level(); got != components.LevelWarning {
331					t.Errorf("footer level = %v, want Warning (nothing failed, a precondition is unmet)", got)
332				}
333				if m.portsModel.confirmModal != nil || m.portsModel.pendingKill != nil {
334					t.Error("the confirmation stayed open after Yes")
335				}
336				if m.portsModel.table.IsBusy("4242") {
337					t.Error("the vanished target was marked busy")
338				}
339			})
340		}
