380	// Rule 128 at 80 columns: the warning is one centred line, whole, and the
381	// footer keeps the height the router budgeted.
382	func TestTheVanishedTargetWarningFitsAt80Columns(t *testing.T) {
383		m, _ := confirmOnNode(t)
