402	// ── S-02a: the wording per platform ──────────────────────────────────────────
403	
404	const (
405		windowsPrompt = "Terminate node.exe (PID 4412)? Windows has no clean stop for this process: it is ended at once and cannot save anything."
406		unixBody      = "Send SIGKILL to sshd (PID 812)?\n\nThe process gets no chance to shut down cleanly."
407		unixHelp      = "Send SIGKILL to the selected process, after confirmation (Ports tab)"
408		windowsHelp   = "End the selected process at once, after confirmation (Ports tab)"
409	)
