411	// windowsNode is a Windows model with the confirmation open on node.exe.
412	func windowsNode(t *testing.T) (*Model, *fakeProcs) {
413		t.Helper()
414		m := feed(t, portsModel(t), tea.WindowSizeMsg{Width: 160, Height: 40})
415		m = feed(t, m, portsDataMsg{ports: []ports.Socket{sock("4412", "node.exe"), sock("812", "sshd")}})
416		m.portsModel.table.Table().SetCursor(0)
417		procs := installProcs(m, true)
418		m = feed(t, m, testutil.Key(keymap.Kill))
419		if m.portsModel.confirmModal == nil {
420			t.Fatal("setup: K on node.exe did not open the confirmation")
421		}
422		return m, procs
423	}
