425	// helpFor is the help line the Ports tab documents for K.
426	func helpFor(m *Model) string {
427		for _, kb := range m.GetHelpContent().KeyBindings {
428			if kb.Key == keymap.Kill && strings.Contains(kb.Description, "(Ports tab)") {
429				return kb.Description
430			}
431		}
432		return ""
433	}
