435	// S-02a criterion 1.
436	func TestWindowsConfirmationIsHonest(t *testing.T) {
437		m, _ := windowsNode(t)
438	
439		if got := squash(modalBody(m)); got != windowsPrompt {
440			t.Errorf("Windows confirmation = %q, want %q", got, windowsPrompt)
441		}
442		if got := squash(killPrompt(killTarget{PID: "4412", Process: "node.exe"}, true)); got != windowsPrompt {
443			t.Errorf("killPrompt(windows) = %q, want %q", got, windowsPrompt)
444		}
445	}
