447	// S-02a criterion 2: one gesture, no wait, no second confirmation.
448	func TestWindowsStopIsOneGesture(t *testing.T) {
449		m, procs := windowsNode(t)
450	
451		m, cmd := step(t, m, components.ConfirmModalYesMsg{})
452		if m.portsModel.confirmModal != nil {
453			t.Error("a second confirmation is open after Yes")
454		}
455		res := runKill(t, cmd) // the command is the kill itself: nothing to wait for
456		if len(procs.killed) != 1 || procs.killed[0] != "4412" {
457			t.Fatalf("signalled %v, want exactly [4412]", procs.killed)
458		}
459	
460		m, _ = step(t, m, res)
461		if m.portsModel.confirmModal != nil {
462			t.Error("a confirmation opened after the result")
463		}
464		if got := m.portsModel.footer.Text(); got != "Process 4412 terminated" {
465			t.Errorf("footer = %q, want %q", got, "Process 4412 terminated")
466		}
467		if m.portsModel.table.IsBusy("4412") {
468			t.Error("the row is still busy after the result")
469		}
470	}
