472	// S-02a criterion 3: nothing on Windows suggests a clean stop, and K stays
473	// "Kill".
474	func TestWindowsLabelsPromiseNoCleanStop(t *testing.T) {
475		m, _ := windowsNode(t)
476		body := modalBody(m) // read before Yes closes the confirmation
477	
