114	// modalLines is the confirmation as rendered, border and padding removed, one
115	// entry per content line, stopping before the buttons.
116	func modalLines(m *Model) []string {
117		var out []string
118		for _, l := range strings.Split(ansi.Strip(m.portsModel.confirmModal.View()), "\n") {
119			l = strings.TrimSpace(strings.Trim(strings.TrimSpace(l), "│┌┐└┘─"))
120			if strings.Contains(l, "Yes") && strings.Contains(l, "No") {
121				break
122			}
123			out = append(out, l)
124		}
125		for len(out) > 0 && out[0] == "" {
126			out = out[1:]
127		}
128		for len(out) > 0 && out[len(out)-1] == "" {
129			out = out[:len(out)-1]
130		}
131		return out
132	}
