13	// Identity tells one process from a later one that got the same PID
14	// (DEVDESK-709). It is the creation stamp in the operating system's own unit,
15	// read once per PID when the table is listed. It is opaque: the interface only
16	// asks Verifiable, and this package compares. The zero value is "unknown", which
17	// Kill refuses, so a caller that forgets the identity cannot send a signal.
18	type Identity struct {
19		kind identityKind
20		raw  uint64
21	}
22	
23	type identityKind uint8
24	
25	const (
26		// identityNone is the zero value: not read, or unreadable.
27		identityNone identityKind = iota
28		// identityKnown carries the creation stamp, in the unit of the OS.
29		identityKnown
30		// identityDeferred is Windows only: the listing stopped reading because its
31		// budget ran out. raw is the listing instant (Unix ns); the stamp is read
32		// when the confirmation opens (ConfirmIdentity).
33		identityDeferred
34	)
35	
36	// The Windows budget and slack (S-01b criterion 7, hypothesis H1).
37	const (
38		// windowsIdentityBudget caps what reading identities adds to one refresh on
39		// Windows. Past it the remaining PIDs are deferred. The starting value of the
40		// story: adjust it from docs/measurements.
41		windowsIdentityBudget = 100 * time.Millisecond
42		// windowsBirthSlack is the granularity allowed between a creation time and the
43		// listing instant before a process counts as born before the listing.
44		windowsBirthSlack = 100 * time.Millisecond
45	)
46	
47	// Verifiable reports whether a stop can still be attempted for the row: the
48	// identity is known, or deferred and read when the confirmation opens.
49	func (i Identity) Verifiable() bool { return i.kind != identityNone }
50	
51	// Conflicts reports whether two identities say, with certainty, that they are
52	// two different processes: both known and different. An unknown or deferred one
53	// never conflicts.
54	func (i Identity) Conflicts(j Identity) bool {
55		return i.kind == identityKnown && j.kind == identityKnown && i.raw != j.raw
56	}
57	
58	// deferredAt is the identity of a PID not read at the listing taken at listedAt.
59	func deferredAt(listedAt time.Time) Identity {
60		return Identity{kind: identityDeferred, raw: uint64(listedAt.UnixNano())} //nolint:gosec // listing instants are after 1970
61	}
62	
63	// IdentityForTest builds a known identity for the fixtures of a test. It panics
64	// outside a test binary.
65	func IdentityForTest(raw uint64) Identity {
66		mustBeUnderTest("IdentityForTest")
67		return Identity{kind: identityKnown, raw: raw}
68	}
69	
70	// DeferredIdentityForTest builds a deferred identity, as a Windows listing does
71	// for a PID it did not read in time. It panics outside a test binary.
72	func DeferredIdentityForTest(listedAt time.Time) Identity {
73		mustBeUnderTest("DeferredIdentityForTest")
74		return deferredAt(listedAt)
75	}
76	
77	func mustBeUnderTest(name string) {
78		if !testing.Testing() {
79			panic("ports: " + name + " is reserved for tests (DEVDESK-709)")
80		}
81	}
82	
83	// UnverifiableError is the refusal when DevDesk cannot tell which process holds
84	// the PID. It is DevDesk's own decision, not the system's: it wraps no OS
85	// sentinel, so the interface cannot read it as "refused by the system".
86	type UnverifiableError struct {
87		PID   int
88		Cause error // for the log only; deliberately not returned by Unwrap
89	}
90	
91	func (e *UnverifiableError) Error() string {
92		return fmt.Sprintf("Cannot verify which process PID %d is — not stopped", e.PID)
93	}
94	
95	// IdentityChangedError is the refusal when the PID is held by another process
96	// than the one that was listed.
97	type IdentityChangedError struct{ PID int }
98	
99	func (e *IdentityChangedError) Error() string {
100		return fmt.Sprintf("PID %d is no longer the process that was listed — not stopped", e.PID)
101	}
102	
103	// parseStartTicks reads the starttime (field 22, ticks since boot) of a
104	// /proc/<pid>/stat line. The command name (field 2) sits between parentheses and
105	// may hold spaces and parentheses itself, so the fields are counted from the
106	// last ")".
107	func parseStartTicks(stat []byte) (uint64, error) {
108		end := bytes.LastIndexByte(stat, ')')
109		if end < 0 {
110			return 0, errors.New("no closing parenthesis in the stat line")
111		}
112		// Fields 3 onward follow the name: field 22 is the 20th of them.
113		const startIndex = 22 - 3
114		fields := bytes.Fields(stat[end+1:])
115		if len(fields) <= startIndex {
116			return 0, fmt.Errorf("the stat line stops at field %d, before starttime (22)", len(fields)+2)
117		}
118		ticks, err := strconv.ParseUint(string(fields[startIndex]), 10, 64)
119		if err != nil {
120			return 0, fmt.Errorf("reading starttime from the stat line: %w", err)
121		}
122		return ticks, nil
123	}
