81			{"PID 1 (criterion 2)", false, "1", "systemd", ports.ProtectedInit, reasonInitText},
82			{"Windows PID 4 (criterion 3)", true, "4", "System", ports.ProtectedWindowsSystem, reasonWindowsText},
83			{"Windows PID 0 (criterion 3)", true, "0", "Idle", ports.ProtectedWindowsSystem, reasonWindowsText},
84		} {
85			t.Run(tt.name, func(t *testing.T) {
86				if got := tt.prot.Reason(); got != tt.reason {
87					t.Fatalf("setup: %v.Reason() = %q, want the agreed %q", tt.prot, got, tt.reason)
