93					t.Fatal("K disappeared from the header instead of being greyed")
94				}
95				if !testutil.ShortcutDisabled(m.GetShortcuts(), keymap.Kill) {
96					t.Error("K is offered on a process DevDesk refuses to signal")
97				}
98				for _, s := range m.GetShortcuts() {
99					if s.Key == keymap.Kill && s.Description != "Kill process" {
100						t.Errorf("greyed K reads %q, want its own label %q", s.Description, "Kill process")
