			m = feed(t, m, portsDataMsg{ports: tt.table})

			m, cmd := step(t, m, components.ConfirmModalYesMsg{})
			got := outcomeOf(m, cmd)

			if got.text != goneWarning || got.level != components.LevelWarning {
